mapper.insert:
/* 인증 완료 회원 가입 */
INSERT INTO USERS (
    USR_LOGIN_ID, USR_PSWD_HASH, USR_NM, USR_EML_ENC, USR_EML_HMAC, USR_EML_CERT_YN,
    USR_TELNO_ENC, USR_ADDR_ENC, USR_DADDR_ENC, USR_ZIP_ENC, USR_BANK_NM_ENC, USR_ACNT_NO_ENC,
    USR_STATUS_CD, USR_ROLE_CD
) VALUES (
    #{usrLoginId}, #{usrPswdHash}, #{usrNm}, #{usrEml}, #{usrEmlHmac}, #{usrEmlCertYn},
    #{usrTelno}, #{usrAddr}, #{usrDaddr}, #{usrZip}, #{usrBankNm}, #{usrAcntNo},
    #{usrStatusCd}, #{usrRoleCd}
)

mapper.update:
/* Refresh Token 해시 갱신 */
UPDATE USERS
SET    USR_REFRESH_TOKEN_HASH = #{refreshTokenHash}
WHERE  USR_SN = #{usrSn}

UPDATE USERS
SET USR_STATUS_CD = #{targetStatusCode},
    USR_REFRESH_TOKEN_HASH = NULL,
    USR_UPDT_ID = #{updaterId}
WHERE USR_SN = #{usrSn}
  AND USR_STATUS_CD = #{expectedStatusCode}
  AND USR_STATUS_CD IN ('USRC0001', 'USRC0002')

/* 일반/제공자 현재 접근 역할 변경 */
UPDATE USERS
SET    USR_ROLE_CD = #{role}
WHERE  USR_SN = #{usrSn}

/* 비밀번호 해시 갱신 */
UPDATE USERS
SET    USR_PSWD_HASH = #{encodedPassword}
WHERE  USR_SN = #{usrSn}
